insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'handstand-libre', 'Handstand libre', 'handstand', '{"handstand","hombros","core"}', '{"peso-corporal"}', 'intermedio', true, '🤸', null, '{"Colocá las manos aproximadamente al ancho de los hombros.","Separá los dedos y presioná el suelo con las yemas.","Mantené los codos extendidos y empujá activamente el suelo.","Elevá los hombros hacia las orejas.","Contraé abdomen y glúteos, piernas juntas.","Mirá entre las manos sin levantar demasiado la cabeza."}', 'Respiración corta y controlada, sin bloquear el aire.', '{"Arquear demasiado la zona lumbar.","Relajar los hombros.","Doblar los codos.","Separar demasiado las piernas.","Hacer demasiados intentos estando fatigado."}', '{"Activá glúteos y abdomen para cerrar la costilla.","Pensá en 'empujar el suelo lejos' para elevar los hombros."}', 'Handstand cara a la pared o contra la pared.', 'Aumentar tiempo en balance libre y reducir la fuerza de entrada.', '{"Práctica contra una pared libre del gimnasio."}', 'Evitar con lesiones de muñeca, hombro o problemas de presión arterial.'
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'handstand-pared', 'Handstand cara a la pared', 'handstand', '{"handstand","hombros","core"}', '{"peso-corporal"}', 'principiante', true, '🧱', null, '{"Caminá con los pies por la pared hasta acercar las manos.","Acercá progresivamente las manos a la pared.","Mantené abdomen y glúteos activos.","No apoyes todo el peso en la pared.","Mantené los hombros elevados."}', 'Inhalá al entrar, respiración controlada durante el hold.', '{"Descolgar los hombros.","Arquear la lumbar y apoyar la panza en la pared."}', '{"Buscá la línea vertical con costillas cerradas."}', 'Alejar un poco las manos de la pared.', 'Acercar las manos y sostener 40s con buena línea.', '{"Cualquier pared despejada."}', null
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'handstand-tecnico', 'Handstand técnico ligero', 'handstand', '{"handstand","hombros","core"}', '{"peso-corporal"}', 'principiante', true, '🎯', null, '{"Intentos suaves, priorizando línea y control.","No busques fatiga: parás cuando la calidad baja.","Trabajá balance y activación escapular."}', null, '{"Convertirlo en trabajo pesado.","Buscar el fallo."}', '{"Calidad sobre cantidad."}', null, null, '{"Pared despejada."}', null
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'pike-pushups', 'Pike push-ups', 'empuje', '{"hombros","brazos","handstand"}', '{"peso-corporal"}', 'principiante', true, '🔺', null, '{"Elevá la cadera formando una V invertida.","Llevá la cabeza hacia adelante y abajo.","Formá un triángulo entre cabeza y manos.","Mantené los codos en un ángulo natural.","Empujá el suelo al subir."}', 'Inhalá al bajar, exhalá al empujar.', '{"Bajar solo con los brazos sin llevar la cabeza adelante."}', '{"Elevá más la cadera para cargar los hombros."}', 'Pike push-up con pies en el suelo.', 'Pies elevados → negativas de HSPU → HSPU asistido en pared.', '{"Press de hombros en máquina si hay molestia."}', null
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'wall-shoulder-taps', 'Shoulder taps en pared', 'handstand', '{"hombros","core","handstand"}', '{"peso-corporal"}', 'intermedio', true, '👐', null, '{"En handstand cara a la pared, separá ligeramente los pies.","Transferí el peso hacia una mano.","Mantené el core activo y despegá la mano de forma controlada.","Evitá girar demasiado la cadera."}', null, '{"Colapsar la cadera al transferir el peso."}', '{"Movimiento lento, sin rebotes."}', 'Shoulder taps en posición de pike o cambios de peso sin despegar la mano.', 'Aumentar repeticiones y tiempo de apoyo en una mano.', '{"Pared despejada."}', null
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'handstand-scapular-shrugs', 'Scapular shrugs en handstand', 'handstand', '{"hombros","handstand"}', '{"peso-corporal"}', 'intermedio', true, '🪜', null, '{"En handstand contra la pared, mantené los codos completamente extendidos.","Elevá y descendé el cuerpo únicamente con las escápulas.","No flexiones los brazos. Usá un rango pequeño y controlado."}', null, '{"Flexionar los codos.","Rango excesivo."}', '{"Aislá el movimiento en las escápulas."}', null, null, '{"Pared despejada."}', null
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'smith-shoulder-press', 'Press de hombros en Smith machine', 'hombros', '{"hombros","brazos"}', '{"smith","banco"}', 'principiante', false, '🏋️', null, '{"Ajustá el banco casi vertical.","Colocá la barra aproximadamente a la altura del mentón.","Mantené los antebrazos verticales.","Descendé de forma controlada.","Empujá sin arquear excesivamente la espalda.","Mantené los pies firmes."}', 'Inhalá al bajar, exhalá al empujar.', '{"Bajar la barra detrás de la cabeza.","Separar excesivamente los codos.","Usar demasiado peso.","Rebotar en la parte inferior."}', '{"Reducí el peso hasta controlar el rango completo."}', null, 'Progresión doble en peso dentro del rango de reps.', '{"Press de hombros en máquina o con mancuernas."}', null
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

insert into public.exercises (id,name,category,primary_muscles,equipment,level,is_bodyweight,image_emoji,video_url,instructions,breathing,common_mistakes,corrections,regression,progression,planet_fitness_substitutions,contraindications) values (
  'dips', 'Fondos (asistidos o libres)', 'empuje', '{"pecho","brazos","hombros"}', '{"peso-corporal","maquina"}', 'principiante', true, '💪', null, '{"Mantené hombros abajo y atrás.","Inclinate ligeramente hacia adelante para enfatizar pecho.","Descendé hasta que el hombro esté aproximadamente al nivel del codo.","No dejes que los hombros colapsen.","Extendé los brazos sin bloquear violentamente."}', 'Inhalá al bajar, exhalá al subir.', '{"Colapsar los hombros.","Rango incompleto."}', '{"Usá asistencia para mantener técnica."}', 'Fondos asistidos en máquina o negativas controladas.', 'Menos asistencia → libres → lastre.', '{"Máquina de fondos asistidos (assisted dip)."}', null
) on conflict (id) do update set name=excluded.name, category=excluded.category, primary_muscles=excluded.primary_muscles, equipment=excluded.equipment, level=excluded.level, is_bodyweight=excluded.is_bodyweight, image_emoji=excluded.image_emoji, instructions=excluded.instructions, breathing=excluded.breathing, common_mistakes=excluded.common_mistakes, corrections=excluded.corrections, regression=excluded.regression, progression=excluded.progression, planet_fitness_substitutions=excluded.planet_fitness_substitutions, contraindications=excluded.contraindications;

