  'machine-chest-press', 'Press de pecho en máquina', 'empuje', '{"pecho","hombros","brazos"}', '{"maquina"}', 'principiante', false, '🎚️', null, '{"Ajustá el asiento para que las manijas queden a la altura del pecho.","Escápulas retraídas, pecho arriba.","Empujá de forma controlada sin bloquear violentamente."}', 'Exhalá al empujar.', '{"Elevar los hombros al empujar."}', '{"Fijá las escápulas contra el respaldo."}', null, null, '{"Press con mancuernas o Smith."}', null
