  'lateral-raises', 'Elevaciones laterales', 'hombros', '{"hombros"}', '{"mancuerna","polea"}', 'principiante', false, '🕊️', null, '{"Utilizá poco peso.","Elevá los brazos hasta aproximadamente la altura de los hombros.","Mantené los codos levemente flexionados.","Controlá la bajada.","Evitá balancearte."}', 'Exhalá al subir.', '{"Usar demasiado peso y balancearse."}', '{"Bajá el peso y priorizá técnica."}', null, 'Aumentar reps antes que peso.', '{"Elevaciones en polea baja."}', null
